{
	if (n < 2 || n > 5)
		return false;

	if (!in(a[0], 1, 8) || !in(a[1], 1, 8))
		return false;

	if (!dim(a[0], 2, 7, n, 3))
		return false;
	if (!dim(a[0], 3, 6, n, 4))
		return false;
	if (!dim(a[0], 4, 5, n, 5))
		return false;

	if (n >= 3 && !in(a[2], -3, 3))
		return false;
	if (n >= 4 && !in(a[3], -2, 2))
		return false;
	if (n >= 5 && !in(a[4], -1, 1))
		return false;

	return true;
}

int
main()
{
	int a1[] = { 1, 6 };
	int a2[] = { 2, 2, -3 };
	int a3[] = { 2, 2, 2 };
	int a4[] = { 3, 1, 2, 1 };
	int a5[] = { 5, 1, 2, 1, 0 };
	int a6[] = { 7, 1, -1 };
	int a7[] = { 8, 8 };

	int a8[] = { 1 };
	int a9[] = { 1, 6, 1 };
	int a10[] = { 2, 1 };
	int a11[] = { 2, 2, -4 };
	int a12[] = { 3, 1, 2 };
	int a13[] = { 7, 7 };
	int a14[] = { 8, 0 };
	int a15[] = { 8, 1, 1 };
	int a16[] = { 8, -1 };

	assert(valid(a1, nelem(a1)) == true);
	assert(valid(a2, nelem(a2)) == true);
	assert(valid(a3, nelem(a3)) == true);
	assert(valid(a4, nelem(a4)) == true);
	assert(valid(a5, nelem(a5)) == true);
	assert(valid(a6, nelem(a6)) == true);
	assert(valid(a7, nelem(a7)) == true);

	assert(valid(a8, nelem(a8)) == false);
	assert(valid(a9, nelem(a9)) == false);
	assert(valid(a10, nelem(a10)) == false);
	assert(valid(a11, nelem(a11)) == false);
	assert(valid(a12, nelem(a12)) == false);
	assert(valid(a13, nelem(a13)) == false);
	assert(valid(a14, nelem(a14)) == false);
	assert(valid(a15, nelem(a15)) == false);
	assert(valid(a16, nelem(a16)) == false);

	return 0;
}
